/**
 * MikroORM test setup for specification tests.
 *
 * Opens each RDBMS block's deployed database from the URL the deploy test's runner resolved for it,
 * and holds one manager per block. Every concrete entity of a block is discovered, since the code a
 * spec runs reaches entities its body never names.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */

import { MikroORM, EntityManager } from '@mikro-orm/core';
import { PostgreSqlDriver } from '@mikro-orm/postgresql';
import { Offer } from '../../src/realestate_deal_service/entities/deal_db/offer.entity';
import { Contract } from '../../src/realestate_deal_service/entities/deal_db/contract.entity';

/** The managers a spec test holds, one per RDBMS block. */
export interface SpecManagers {
  readonly em: EntityManager;
}

let opened: { orm: MikroORM; em: EntityManager }[] = [];

function requireDatabaseUrl(variable: string): string {
  const databaseUrl = process.env[variable];
  if (!databaseUrl) {
    throw new Error(
      `${variable} environment variable is required for spec tests.\n` +
      'Spec tests must run against a deployed database (via deploy tests).'
    );
  }
  return databaseUrl;
}

/**
 * Open every block's database.
 */
export async function initTestDatabase(): Promise<SpecManagers> {
  const emOrm = await MikroORM.init({
    entities: [
      Offer,
      Contract,
    ],
    driver: PostgreSqlDriver,
    clientUrl: requireDatabaseUrl("DEAL_DB_DATABASE_URL"),
    debug: false,
    allowGlobalContext: true, // Allow EM access outside request context in tests
  });
  const em = emOrm.em.fork();
  opened.push({ orm: emOrm, em: em });
  return { em };
}

/**
 * Close every MikroORM connection.
 */
export async function closeTestDatabase(): Promise<void> {
  const closing = opened;
  opened = [];
  for (const { orm } of closing) {
    await orm.close(true);
  }
}

/**
 * Delete every row of every block, children first as the metadata orders them, and forget what the
 * managers loaded.
 */
export async function clearTestData(): Promise<void> {
  if (opened.length === 0) {
    throw new Error('Database not initialized. Call initTestDatabase() first.');
  }
  for (const { orm, em } of opened) {
    await orm.schema.clearDatabase({ truncate: false });
    em.clear();
  }
}
